'use strict';
const $=s=>document.querySelector(s);
const state={view:'explorar',notation:'latin',root:0,scale:'all',frets:12,hide:false,chordId:'0-major',selected:{string:4,fret:3},sequence:Music.presets.pop.ids.map(id=>({id,beats:4})),bpm:80,loop:true,click:true,sound:true,volume:50,active:0,playing:false,paused:false,beat:0,quiz:null,correct:0,answered:0};
let timer=null,nextBeat=0,toastTimer=null,flashTimer=null;
const headings={explorar:['01 / EXPLORAR','Conoce tu mástil','Reconecta con las notas. Toca una cuerda y escucha dónde estás.'],acordes:['02 / ACORDES','Dale forma al sonido','Encuentra tus acordes, escucha sus matices y vuelve a sentirlos en los dedos.'],progresiones:['03 / PROGRESIONES','Un acorde lleva a otro','Construye una secuencia y encuentra tu ritmo, cambio a cambio.'],practicar:['04 / PRACTICAR','Que tus dedos recuerden','Encuentra la nota señalada. Sin prisas: cada intento cuenta.']};
function safeLoad(){try{const p=JSON.parse(localStorage.getItem('entre-cuerdas-v1'));if(!p)return;if(['latin','english'].includes(p.notation))state.notation=p.notation;if(Number.isFinite(p.bpm))state.bpm=Math.max(30,Math.min(220,Math.round(p.bpm)));if(Array.isArray(p.sequence)&&p.sequence.length<=32&&p.sequence.every(s=>{try{Music.fromId(s.id);return Number.isInteger(s.beats)&&s.beats>=1&&s.beats<=32;}catch{return false;}}))state.sequence=p.sequence;for(const key of ['loop','click','sound'])if(typeof p[key]==='boolean')state[key]=p[key];}catch{}}
function save(){try{localStorage.setItem('entre-cuerdas-v1',JSON.stringify({notation:state.notation,sequence:state.sequence,bpm:state.bpm,loop:state.loop,click:state.click,sound:state.sound}));}catch{}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800);}
function note(pc){return Music.note(pc,state.notation);}
function currentChord(){return Music.fromId(state.view==='progresiones'&&state.sequence.length?state.sequence[Math.min(state.active,state.sequence.length-1)].id:state.chordId);}
function scaleNotes(){const s=Music.scales[state.scale];return s.degrees?Music.spell(state.root,s.intervals,s.degrees,state.notation):s.intervals.map(i=>note((state.root+i)%12));}
function boardName(pc){if(state.view==='explorar'){const s=Music.scales[state.scale],index=s.intervals.findIndex(i=>(state.root+i)%12===pc);if(index>=0)return scaleNotes()[index];}if(['acordes','progresiones'].includes(state.view)){const c=currentChord(),q=Music.qualities[c.quality],i=c.pcs.indexOf(pc);if(i>=0)return Music.spell(c.root,q.intervals,q.degrees,state.notation)[i];}return note(pc);}
function rootOptions(value){return Music.english.map((_,i)=>`<option value="${i}" ${i===value?'selected':''}>${note(i)}</option>`).join('');}
function chordOptions(id){return Object.entries(Music.qualities).map(([quality,q])=>`<optgroup label="${q.label}">${Array.from({length:12},(_,root)=>Music.chord(root,quality)).map(c=>`<option value="${c.id}" ${id===c.id?'selected':''}>${Music.chordName(c,state.notation)}</option>`).join('')}</optgroup>`).join('');}
function render(){const h=headings[state.view];$('#eyebrow').textContent=h[0];$('#page-title').innerHTML=h[1]+'<span>.</span>';$('#page-description').textContent=h[2];document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===state.view);b.setAttribute('aria-current',b.dataset.view===state.view?'page':'false');});document.querySelectorAll('[data-notation]').forEach(b=>{b.classList.toggle('selected',b.dataset.notation===state.notation);b.setAttribute('aria-pressed',String(b.dataset.notation===state.notation));});renderControls();renderBoard();renderDetail();renderLower();}
function renderControls(){let content='';
if(state.view==='explorar')content=`<label class="field"><span>Mostrar</span><select id="scale-select">${Object.entries(Music.scales).map(([id,s])=>`<option value="${id}" ${state.scale===id?'selected':''}>${s.label}</option>`).join('')}</select></label><label class="field"><span>Tónica</span><select id="root-select">${rootOptions(state.root)}</select></label><label class="check-label control-end"><input type="checkbox" id="hide-notes" ${state.hide?'checked':''}> Ocultar nombres</label>`;
if(state.view==='acordes'){const c=currentChord();content=`<label class="field"><span>Fundamental</span><select id="chord-root">${rootOptions(c.root)}</select></label><label class="field"><span>Tipo de acorde</span><select id="chord-quality">${Object.entries(Music.qualities).map(([id,q])=>`<option value="${id}" ${c.quality===id?'selected':''}>${q.label}</option>`).join('')}</select></label><span class="help-text control-end">84 acordes · abiertos y con cejilla</span>`;}
if(state.view==='progresiones')content=`<span class="help-text">${state.playing?'Sigue el acorde marcado y prepárate para el siguiente.':'Elige los acordes y cuántos pulsos dura cada uno.'}</span><label class="volume-field control-end">Volumen <input id="volume" type="range" min="0" max="100" value="${state.volume}" aria-label="Volumen"></label>`;
if(state.view==='practicar')content=`<label class="field"><span>Zona del mástil</span><select id="quiz-range"><option value="5" ${state.quiz?.range===5?'selected':''}>Primeros 5 trastes</option><option value="12" ${state.quiz?.range===12?'selected':''}>Todo el mástil</option></select></label><span class="help-text control-end">Pulsa la posición marcada para escucharla.</span>`;
$('#view-controls').innerHTML=content;}
function renderBoard(){const isChord=['acordes','progresiones'].includes(state.view),c=isChord?currentChord():null,quiz=state.view==='practicar',root=c?.root??state.root,maxFret=c?Math.max(...c.frets):0,frets=Math.max(state.frets,maxFret>12?15:12);const board=$('#fretboard');board.style.setProperty('--frets',frets);document.getElementById("fret-count").value=String(frets);
$('#board-title').textContent=quiz?'¿Qué nota está aquí?':isChord?`${Music.chordName(c,state.notation)} · ${Music.qualities[c.quality].label.toLowerCase()}`:state.scale==='all'?'El mapa del mástil':state.scale==='single'?`Encuentra ${note(state.root)}`:`${Music.scales[state.scale].label} de ${note(state.root)}`;
document.querySelector('.chord-legend').style.display=isChord?'inline':'none';let html='';for(let f=0;f<=frets;f++)html+=`<span class="fret-label">${f===0?'AIRE':f}</span>`;
Music.tuning.forEach((midi,s)=>{for(let f=0;f<=frets;f++){const pc=(midi+f)%12,shapeFret=c?.frets[5-s],chordPosition=isChord&&shapeFret===f,muted=isChord&&shapeFret===-1&&f===0,allowed=Music.scales[state.scale].intervals.some(i=>(root+i)%12===pc),target=quiz&&state.quiz?.string===s&&state.quiz?.fret===f,visible=quiz?target:isChord?chordPosition||muted:allowed,hidden=!visible||(!isChord&&!quiz&&state.hide);const display=quiz?(target?(state.quiz.revealed?note(pc):'?'):''):muted?'×':boardName(pc);const accessible=quiz||state.hide&&!isChord?`Cuerda ${s+1}, traste ${f}${target?', nota a adivinar':''}`:`${boardName(pc)}, cuerda ${s+1}, ${f===0?'al aire':`traste ${f}`}${muted?', no tocar':''}`;
html+=`<button class="fret-cell ${f===0?'open':''} ${target?'target':''} ${muted?'muted-chord':''}" data-string="${s}" data-fret="${f}" aria-label="${accessible}" style="--string-width:${1+s*.25}px"><span class="note-dot ${pc===root&&!muted?'root':''} ${hidden?'hidden-note':''}">${hidden?'':display}</span></button>`;}});
for(let f=0;f<=frets;f++)html+=`<span class="fret-marker">${[3,5,7,9,12,15].includes(f)?'<i></i>':''}${f===12?'<i></i>':''}</span>`;board.innerHTML=html;}
function diagram(c){const positive=c.frets.filter(f=>f>0),start=Math.min(...positive)>3?Math.min(...positive):1,rows=Math.max(4,Math.max(...positive)-start+1),height=rows*26+47;let svg=`<svg class="diagram" viewBox="0 0 170 ${height}" role="img" aria-label="Diagrama de ${Music.chordName(c,state.notation)}. Cuerdas de sexta a primera: ${c.frets.map(f=>f<0?'no tocar':f).join(', ')}">`;
for(let f=0;f<=rows;f++)svg+=`<line x1="30" y1="${27+f*26}" x2="145" y2="${27+f*26}" stroke="${f===0&&start===1?'#667263':'#b4bcae'}" stroke-width="${f===0&&start===1?4:1}"/>`;
for(let s=0;s<6;s++)svg+=`<line x1="${30+s*23}" y1="27" x2="${30+s*23}" y2="${27+rows*26}" stroke="#96a18e" stroke-width="${1.5-s*.15}"/>`;
if(start>1)svg+=`<text x="6" y="45" fill="#637359" font-size="11">${start}fr</text>`;
if(c.barre)svg+=`<line x1="${30+c.barre.from*23}" x2="${30+c.barre.to*23}" y1="${40+(c.barre.fret-start)*26}" y2="${40+(c.barre.fret-start)*26}" stroke="#567449" stroke-width="14" stroke-linecap="round"/>`;
c.frets.forEach((f,s)=>{const x=30+s*23;if(f<=0)svg+=`<text x="${x}" y="17" text-anchor="middle" font-size="14" fill="#566a4f">${f<0?'×':'○'}</text>`;else svg+=`<circle cx="${x}" cy="${40+(f-start)*26}" r="8.5" fill="#2c6258"/><text x="${x}" y="${44+(f-start)*26}" text-anchor="middle" fill="white" font-size="10">${c.fingers[s]||'•'}</text>`;svg+=`<text x="${x}" y="${44+rows*26}" text-anchor="middle" font-size="10" fill="#6f7e66">${6-s}</text>`;});return svg+'</svg>';}
function renderDetail(){const panel=$('#detail-panel');panel.className='detail-panel card';
if(['acordes','progresiones'].includes(state.view)){const c=currentChord(),q=Music.qualities[c.quality];panel.classList.add('chord-detail');const notes=Music.spell(c.root,q.intervals,q.degrees,state.notation);panel.innerHTML=`<span class="detail-tag">${state.view==='progresiones'?'ACORDE ACTUAL':'ASÍ SE TOCA'}</span><div class="big-note">${Music.chordName(c,state.notation)}</div><p class="detail-subtitle">${q.label}${c.barre?' · con cejilla':''}</p>${diagram(c)}<div class="note-chips">${notes.map(n=>`<span class="chip">${n}</span>`).join('')}</div><p class="detail-description">1 índice · 2 medio · 3 anular · 4 meñique. Cuerdas de 6.ª a 1.ª.</p><button class="btn primary" id="listen-chord">▷ Escuchar acorde</button>${state.view==='acordes'?'<button class="btn soft" id="add-current">＋ Añadir a progresión</button>':'<div class="meter-track"><div class="meter-fill" id="step-meter"></div></div>'}`;return;}
if(state.view==='practicar'){const q=state.quiz;panel.innerHTML=`<span class="detail-tag">TU RETO</span><div class="big-note">${q?.revealed?note(q.pc):'?'}</div><p class="detail-subtitle">Cuerda ${(q?.string??0)+1} · traste ${q?.fret??0}</p><div class="note-chips"><span class="chip">${state.correct} / ${state.answered} aciertos</span></div><p class="detail-description">Parte de la cuerda al aire y avanza un semitono por traste. Mi–Fa y Si–Do van seguidos.</p><button class="btn soft" id="reveal-note" ${q?.revealed?'disabled':''}>Ver respuesta</button>`;return;}
const sel=state.selected,pc=(Music.tuning[sel.string]+sel.fret)%12,midi=Music.tuning[sel.string]+sel.fret;panel.innerHTML=`<span class="detail-tag">LA NOTA QUE EXPLORAS</span><div class="big-note">${boardName(pc)}</div><p class="detail-subtitle">${Music.note(pc,state.notation==='latin'?'english':'latin')} · octava ${Math.floor(midi/12)-1}</p><div class="note-chips"><span class="chip">Cuerda ${sel.string+1}</span><span class="chip">${sel.fret===0?'Al aire':`Traste ${sel.fret}`}</span></div><p class="detail-description">${pc===state.root?'Es la tónica que has elegido. Búscala en las otras cuerdas para conectar posiciones.':'La misma nota aparece en distintos lugares del mástil. Escucha cómo cambia su altura.'}</p><button class="btn primary" id="listen-note">▷ Escuchar nota</button>`;}
function cards(firstTitle,firstText,secondTitle,secondText){return `<div class="learning-cards"><article class="learning-card"><span class="learning-icon">↗</span><div><h3>${firstTitle}</h3><p>${firstText}</p></div></article><article class="learning-card peach"><span class="learning-icon">♮</span><div><h3>${secondTitle}</h3><p>${secondText}</p></div></article></div>`;}
function renderLower(){
if(state.view==='explorar'){const all=['all','single'].includes(state.scale),pcs=Music.scales[state.scale].intervals.map(i=>(i+state.root)%12),spelled=scaleNotes();$('#lower-panel').innerHTML=`<div class="section-header"><div><h2>${all?'Las doce notas':'Las notas de tu escala'}</h2><p>${all?'Elige una nota para resaltarla.':'Pulsa una nota para escucharla.'}</p></div>${state.scale==='single'?'<button class="text-btn" id="show-all">Ver todas ↗</button>':''}</div><div class="notes-strip" ${!all?`style="grid-template-columns:repeat(${pcs.length},1fr)"`:''}>${(all?Array.from({length:12},(_,i)=>i):pcs).map((pc,i)=>`<button class="note-tile ${pc===state.root?'active':''} ${[1,3,6,8,10].includes(pc)?'accidental':''}" data-note="${pc}">${all?note(pc):spelled[i]}<small>${Music.note(pc,state.notation==='latin'?'english':'latin')}</small></button>`).join('')}</div>`+cards('Un traste, un semitono','Cada traste sube la nota un semitono. Del traste 0 al 12 recorres una octava: la misma nota, más aguda.','Dos parejas sin nota intermedia','Entre Mi y Fa, y entre Si y Do, solo hay un semitono. En las demás notas naturales hay un tono (dos trastes).');}
if(state.view==='acordes'){const c=currentChord();$('#lower-panel').innerHTML=`<div class="section-header"><div><h2>La familia de ${Music.note(c.root,state.notation,[3,8,10].includes(c.root))}</h2><p>Una fundamental, distintos colores.</p></div><button class="text-btn" data-view="progresiones">Ir a mi progresión ↗</button></div><div class="chord-grid">${Object.entries(Music.qualities).map(([quality,q])=>{const other=Music.chord(c.root,quality);return `<button class="chord-tile ${other.id===c.id?'active':''}" data-chord="${other.id}"><strong>${Music.chordName(other,state.notation)}</strong><small>${q.label}</small></button>`;}).join('')}</div>`+cards('Cuerdas abiertas, cuerdas en silencio','○ significa que la cuerda suena al aire. × significa que debes evitar tocarla. Los números dentro de los puntos indican los dedos.','La cejilla es un puente','La barra del diagrama indica que el índice pisa varias cuerdas en el mismo traste. Acerca el dedo al metal, sin colocarlo encima.');}
if(state.view==='progresiones')renderProgression();if(state.view==='practicar')renderQuiz();}
function renderProgression(){$('#lower-panel').innerHTML=`<section class="progression-editor"><div class="progression-toolbar"><h2>Tu secuencia</h2><label class="sr-only" for="preset">Progresión de ejemplo</label><select id="preset"><option value="">Prueba una progresión…</option>${Object.entries(Music.presets).map(([id,p])=>`<option value="${id}">${p.name}</option>`).join('')}</select><button class="btn ghost" id="clear-sequence" ${!state.sequence.length?'disabled':''}>Vaciar</button></div><div class="sequence">${state.sequence.length?state.sequence.map((step,i)=>`<article class="step ${i===state.active?'active':''}" data-step="${i}"><div class="step-top"><button class="text-btn step-number" data-select-step="${i}" aria-label="Mostrar acorde ${i+1}">ACORDE ${String(i+1).padStart(2,'0')}</button><button class="icon-btn" data-remove-step="${i}" aria-label="Eliminar acorde ${i+1}">×</button></div><label class="sr-only" for="step-${i}">Acorde ${i+1}</label><select id="step-${i}" data-step-chord="${i}">${chordOptions(step.id)}</select><label class="duration-field"><input type="number" min="1" max="32" value="${step.beats}" data-step-beats="${i}" aria-label="Pulsos del acorde ${i+1}"> pulsos <span data-seconds="${i}">· ${seconds(step.beats)} s</span></label><div class="step-order"><button class="icon-btn" data-move="${i},-1" ${i===0?'disabled':''} aria-label="Mover acorde ${i+1} a la izquierda">←</button><button class="icon-btn" data-move="${i},1" ${i===state.sequence.length-1?'disabled':''} aria-label="Mover acorde ${i+1} a la derecha">→</button></div></article>`).join(''):'<p class="empty-sequence">Tu próxima progresión empieza con un acorde.</p>'}<button class="add-step" id="add-step" ${state.sequence.length>=32?'disabled':''}><span>＋</span>Añadir acorde</button></div><div class="transport"><button class="btn primary" id="play-sequence" ${!state.sequence.length?'disabled':''}>${state.playing?'Ⅱ Pausar':state.paused?'▷ Continuar':'▷ Reproducir'}</button><button class="btn ghost" id="stop-sequence" aria-label="Detener y volver al principio">■</button><label class="tempo-control">Tempo <input id="bpm" type="number" min="30" max="220" value="${state.bpm}"> <span>BPM</span></label><label class="check-label"><input id="loop" type="checkbox" ${state.loop?'checked':''}> Bucle</label><label class="check-label"><input id="metronome" type="checkbox" ${state.click?'checked':''}> Metrónomo</label><label class="check-label"><input id="chord-sound" type="checkbox" ${state.sound?'checked':''}> Acordes</label><div class="beat-display" id="beat-display">${beatMarkup()}</div></div><p class="sequence-info" id="sequence-info">${sequenceInfo()}</p></section>`+cards('Primero fluidez, después velocidad','Empieza a 60–80 BPM y usa cuatro pulsos por acorde. Baja el tempo si necesitas más tiempo para preparar el siguiente cambio.','El tiempo lo decides tú','A 60 BPM, cada pulso dura un segundo. A 120 BPM, medio segundo. La duración se calcula junto a cada acorde.');}
function seconds(beats){return(beats*60/state.bpm).toLocaleString('es-ES',{maximumFractionDigits:1});}
function sequenceInfo(){const total=state.sequence.reduce((n,s)=>n+s.beats,0);return `${state.sequence.length} acordes · ${total} pulsos · ${seconds(total)} s por vuelta · Se guarda en este navegador`;}
function beatMarkup(){const total=state.sequence[state.active]?.beats??4;return `${Array.from({length:Math.min(total,8)},(_,i)=>`<i class="beat-dot ${state.playing&&i===state.beat%8?'on':''}"></i>`).join('')}<span> ${state.playing||state.paused?state.beat+1:'—'} / ${total}</span>`;}
function refreshTransport(){const play=$('#play-sequence');if(play)play.textContent=state.playing?'Ⅱ Pausar':state.paused?'▷ Continuar':'▷ Reproducir';if($('#beat-display'))$('#beat-display').innerHTML=beatMarkup();document.querySelectorAll('.step').forEach(el=>el.classList.toggle('active',Number(el.dataset.step)===state.active));if($('#step-meter'))$('#step-meter').style.width=state.playing||state.paused?`${(state.beat+1)/(state.sequence[state.active]?.beats??1)*100}%`:'0';}
function stop(reset=true){clearTimeout(timer);timer=null;GuitarAudio.stop();state.playing=false;state.paused=false;state.beat=0;if(reset)state.active=0;refreshTransport();}
let starting=false;
async function play(){if(state.playing){clearTimeout(timer);GuitarAudio.stop();state.playing=false;state.paused=true;refreshTransport();return;}if(!state.sequence.length||starting)return;starting=true;try{await GuitarAudio.ready();}catch{toast('No se pudo activar el audio. Prueba en un navegador actualizado.');starting=false;return;}starting=false;if(state.view!=='progresiones'||!state.sequence.length)return;state.playing=true;state.paused=false;nextBeat=performance.now();tick(true);}
function tick(first=false){if(!state.playing)return;let change=first;if(!first){state.beat++;if(state.beat>=state.sequence[state.active].beats){state.beat=0;state.active++;change=true;if(state.active>=state.sequence.length){if(!state.loop){stop();renderBoard();renderDetail();toast('Vuelta terminada. Buen trabajo.');return;}state.active=0;}}}if(change){renderBoard();renderDetail();if(state.sound)GuitarAudio.strum(currentChord(),state.sequence[state.active].beats*60/state.bpm);const step=document.querySelector(`[data-step="${state.active}"]`);if(step){const sequence=step.parentElement;sequence.scrollTo({left:step.offsetLeft-sequence.offsetLeft,behavior:'smooth'});}}if(state.click)GuitarAudio.click(state.beat===0);refreshTransport();nextBeat+=60000/state.bpm;if(nextBeat<performance.now())nextBeat=performance.now()+60000/state.bpm;timer=setTimeout(tick,Math.max(0,nextBeat-performance.now()));}
function newQuiz(range=state.quiz?.range??5){const old=state.quiz;let string,fret;do{string=Math.floor(Math.random()*6);fret=Math.floor(Math.random()*(range+1));}while(old&&old.string===string&&old.fret===fret);state.quiz={string,fret,pc:(Music.tuning[string]+fret)%12,range,revealed:false,result:''};}
function renderQuiz(){const q=state.quiz;$('#lower-panel').innerHTML=`<section class="quiz-box"><div class="section-header" style="margin-top:0"><div><h2>${q.revealed?'Ya tienes una nota más.':'¿Cómo se llama la nota marcada?'}</h2></div><span class="quiz-score">${state.correct} de ${state.answered} aciertos</span></div><div class="quiz-options">${Music.latin.map((_,pc)=>`<button data-answer="${pc}" ${q.revealed?'disabled':''}>${note(pc)}</button>`).join('')}</div><p class="quiz-message" role="status">${q.result||'Puedes escucharla pulsando el signo de interrogación en el mástil.'}</p><button class="btn primary" id="next-question">${q.revealed?'Siguiente nota →':'Saltar nota →'}</button></section>`;}
async function soundNote(string,fret){try{await GuitarAudio.ready();GuitarAudio.pluck(Music.tuning[string]+fret);}catch{toast('El audio no está disponible en este navegador.');}}
function navigate(view){if(!headings[view])return;stop();state.view=view;if(view==='practicar'&&!state.quiz)newQuiz();try{history.replaceState(null,'','#'+view);window.scrollTo({top:0});}catch{}render();}
function editSequence(fn){stop(false);fn();state.active=Math.max(0,Math.min(state.active,state.sequence.length-1));save();renderBoard();renderDetail();renderProgression();}
document.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(!b)return;
if(b.dataset.view){navigate(b.dataset.view);return;}
if(b.classList.contains('brand')){e.preventDefault();navigate('explorar');return;}
if(b.dataset.notation){state.notation=b.dataset.notation;save();render();return;}
if(b.dataset.string!==undefined){const string=Number(b.dataset.string),fret=Number(b.dataset.fret);if(['acordes','progresiones'].includes(state.view)&&currentChord().frets[5-string]===-1&&fret===0){toast('Esta cuerda no se toca en este acorde.');return;}await soundNote(string,fret);document.querySelectorAll('.played').forEach(el=>el.classList.remove('played'));b.classList.add('played');clearTimeout(flashTimer);flashTimer=setTimeout(()=>b.classList.remove('played'),650);if(state.view==='explorar'){state.selected={string,fret};renderDetail();}return;}
if(b.dataset.note!==undefined){const pc=Number(b.dataset.note);if(['all','single'].includes(state.scale)){state.root=pc;state.scale='single';const string=4,fret=(pc-Music.tuning[string]%12+12)%12;state.selected={string,fret};render();}await soundNote(0,(pc-4+12)%12);return;}
if(b.dataset.chord){state.chordId=b.dataset.chord;render();return;}
if(b.dataset.selectStep!==undefined){stop(false);state.active=Number(b.dataset.selectStep);renderBoard();renderDetail();refreshTransport();return;}
if(b.dataset.removeStep!==undefined){editSequence(()=>state.sequence.splice(Number(b.dataset.removeStep),1));return;}
if(b.dataset.move){const[i,d]=b.dataset.move.split(',').map(Number);if(i+d<0||i+d>=state.sequence.length)return;editSequence(()=>{[state.sequence[i],state.sequence[i+d]]=[state.sequence[i+d],state.sequence[i]];state.active=i+d;});return;}
if(b.dataset.answer!==undefined){const q=state.quiz;if(q.revealed)return;const correct=Number(b.dataset.answer)===q.pc;state.answered++;if(correct)state.correct++;q.revealed=true;q.result=correct?`¡Exacto! Es ${note(q.pc)}. Sigue así.`:`Es ${note(q.pc)}. Desde ${note(Music.tuning[q.string]%12)} al aire, avanza ${q.fret} semitonos.`;renderBoard();renderDetail();renderQuiz();return;}
switch(b.id){case'show-all':state.scale='all';render();break;case'listen-note':await soundNote(state.selected.string,state.selected.fret);break;case'listen-chord':try{await GuitarAudio.ready();GuitarAudio.strum(currentChord());}catch{toast('No se pudo activar el audio.');}break;case'add-current':if(state.sequence.length>=32){toast('La secuencia admite hasta 32 acordes.');break;}state.sequence.push({id:state.chordId,beats:4});save();toast(`${Music.chordName(currentChord(),state.notation)} añadido a tu progresión`);break;case'add-step':editSequence(()=>{if(state.sequence.length<32)state.sequence.push({id:state.chordId,beats:4});});break;case'clear-sequence':editSequence(()=>state.sequence=[]);break;case'play-sequence':await play();break;case'stop-sequence':stop();renderBoard();renderDetail();break;case'next-question':newQuiz();renderBoard();renderDetail();renderQuiz();break;case'reveal-note':if(!state.quiz.revealed){state.answered++;state.quiz.revealed=true;state.quiz.result=`Es ${note(state.quiz.pc)}. Prueba a encontrarla también en otra cuerda.`;renderBoard();renderDetail();renderQuiz();}break;}});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.stepChord!==undefined){editSequence(()=>{state.sequence[Number(t.dataset.stepChord)].id=t.value;state.active=Number(t.dataset.stepChord);});return;}if(t.dataset.stepBeats!==undefined){editSequence(()=>state.sequence[Number(t.dataset.stepBeats)].beats=Math.max(1,Math.min(32,Math.round(Number(t.value)||4))));return;}
switch(t.id){case'scale-select':state.scale=t.value;render();break;case'root-select':state.root=Number(t.value);render();break;case'hide-notes':state.hide=t.checked;renderBoard();break;case'fret-count':state.frets=Number(t.value);renderBoard();break;case'chord-root':state.chordId=`${t.value}-${currentChord().quality}`;render();break;case'chord-quality':state.chordId=`${currentChord().root}-${t.value}`;render();break;case'preset':if(t.value)editSequence(()=>{state.sequence=Music.presets[t.value].ids.map(id=>({id,beats:4}));state.active=0;});break;case'bpm':state.bpm=Math.max(30,Math.min(220,Math.round(Number(t.value)||80)));t.value=state.bpm;save();document.querySelectorAll('[data-seconds]').forEach(el=>el.textContent=`· ${seconds(state.sequence[Number(el.dataset.seconds)].beats)} s`);$('#sequence-info').textContent=sequenceInfo();if(state.playing){clearTimeout(timer);nextBeat=performance.now()+60000/state.bpm;timer=setTimeout(tick,60000/state.bpm);}break;case'loop':state.loop=t.checked;save();break;case'metronome':state.click=t.checked;save();break;case'chord-sound':state.sound=t.checked;save();break;case'quiz-range':newQuiz(Number(t.value));renderBoard();renderDetail();renderQuiz();break;}});
document.addEventListener('input',e=>{if(e.target.id==='volume'){state.volume=Number(e.target.value);GuitarAudio.setVolume(state.volume/100);}});
document.addEventListener('keydown',e=>{if(e.code==='Space'&&state.view==='progresiones'&&!e.target.closest('input,select,button,a')){e.preventDefault();play();}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&state.playing){clearTimeout(timer);GuitarAudio.stop();state.playing=false;state.paused=true;refreshTransport();toast('Reproducción pausada al cambiar de pestaña.');}});
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(headings[v])navigate(v);});
safeLoad();const initial=location.hash.slice(1);if(headings[initial])state.view=initial;if(state.view==='practicar')newQuiz();render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'configure_guitar_progression',title:'Configurar progresión de guitarra',description:'Sustituye la secuencia visible de práctica y su tempo. No inicia audio. IDs como 0-major (Do), 9-minor (Lam).',inputSchema:{type:'object',properties:{bpm:{type:'integer',minimum:30,maximum:220},chords:{type:'array',maxItems:32,items:{type:'object',properties:{id:{type:'string'},beats:{type:'integer',minimum:1,maximum:32}},required:['id','beats'],additionalProperties:false}}},required:['bpm','chords'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!Number.isInteger(input.bpm)||input.bpm<30||input.bpm>220||!Array.isArray(input.chords)||input.chords.length>32)throw Error('Tempo o secuencia no válidos');const sequence=input.chords.map(s=>{Music.fromId(s.id);if(!Number.isInteger(s.beats)||s.beats<1||s.beats>32)throw Error('Duración no válida');return{id:s.id,beats:s.beats};});stop();state.sequence=sequence;state.bpm=input.bpm;save();navigate('progresiones');return{bpm:state.bpm,chords:state.sequence};}})).catch(()=>{});}catch{}}


